const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def minPathSum(self, grid: List[List[int]]) -> int:", "        (m, n) = (len(grid), len(grid[0]))", "        f = [[0] * n for _ in range(m)]", "        f[0][0] = grid[0][0]", "        for i in range(1, m):", "            f[i][0] = f[i - 1][0] + grid[i][0]", "        for j in range(1, n):", "            f[0][j] = f[0][j - 1] + grid[0][j]", "        for i in range(1, m):", "            for j in range(1, n):", "                f[i][j] = min(f[i - 1][j], f[i][j - 1]) + grid[i][j]", "        return f[-1][-1]"], "Java": ["import java.util.*;", "class Solution {", "    public int minPathSum(int[][] grid) {", "        int m = grid.length, n = grid[0].length;", "        int[][] f = new int[m][n];", "        f[0][0] = grid[0][0];", "        for (int i = 1; i < m; ++i) {", "            f[i][0] = f[i - 1][0] + grid[i][0];", "        }", "        for (int j = 1; j < n; ++j) {", "            f[0][j] = f[0][j - 1] + grid[0][j];", "        }", "        for (int i = 1; i < m; ++i) {", "            for (int j = 1; j < n; ++j) {", "                f[i][j] = Math.min(f[i - 1][j], f[i][j - 1]) + grid[i][j];", "            }", "        }", "        return f[m - 1][n - 1];", "    }", "}"]};
